@using sv_19b4d8530e9242c280b023e5c6b7e30a.Models

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-desc">@TruncatedDescription</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<int> OnSelected { get; set; }

    private string TruncatedDescription =>
        Channel.Description.Length > 40
            ? Channel.Description[..40] + "…"
            : Channel.Description;

    private async Task OnClick() => await OnSelected.InvokeAsync(Channel.Id);
}

.channel-item {
    padding: 8px 12px;
    cursor: pointer;
    border-bottom: 1px solid #3a3a3a;
    position: relative;
}

.channel-item:hover {
    background-color: #3a3a4a;
}

.channel-item.active {
    background-color: #4a4a5e;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    color: #e0e0e0;
}

.channel-desc {
    font-size: 0.75rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 10px;
    right: 10px;
    background-color: #e04040;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

@using sv_19b4d8530e9242c280b023e5c6b7e30a.Models

<div class="message-bubble @(IsThreadStarter ? "thread-starter" : "")"
     @onmouseenter="() => showActions = true"
     @onmouseleave="OnMouseLeave">
    <div class="msg-header">
        <span class="msg-author">@Message.Author</span>
        <span class="msg-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="msg-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="msg-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (IsThreadStarter)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ThreadReplyCount replies
        </button>
    }

    @if (showActions)
    {
        <div class="msg-actions">
            <button class="action-btn" title="Reply" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">💬</button>
            <button class="action-btn" title="React" @onclick="ToggleEmojiPicker">😀</button>
        </div>
    }

    @if (showEmojiPicker)
    {
        <div class="emoji-picker">
            @foreach (var emoji in commonEmojis)
            {
                <button class="emoji-btn" @onclick="() => PickEmoji(emoji)">@emoji</button>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public bool IsThreadStarter { get; set; }
    [Parameter] public int ThreadReplyCount { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task PickEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private void OnMouseLeave()
    {
        showActions = false;
        showEmojiPicker = false;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

.message-bubble {
    padding: 8px 16px;
    position: relative;
    border-radius: 4px;
}

.message-bubble:hover {
    background-color: #f8f8fa;
}

.msg-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
